-- Ejecutar en Supabase -> SQL Editor -> New query -> Run.
-- Parte 6 de 7. Requiere 01_esquema.sql (columnas profile, skills y
-- mindscapes de characters) y 04_personajes_zzz.sql.
--
-- Datos de los agentes de Zenless Zone Zero sacados de HoYoWiki, la wiki oficial de
-- HoYoverse, con los textos oficiales en espanol:
--   profile     -> sexo, afiliacion, estatura, cumpleanos, actores de voz y version.
--   skills      -> las seis categorias de tecnicas (ataque normal, evasion,
--                  tecnica de apoyo, tecnica especial, tecnica en cadena y
--                  habilidad fundamental) con sus valores por nivel y los
--                  materiales para subirlas.
--   mindscapes  -> los seis niveles de Cine mental.
-- Ademas, los agentes que no tenian biografia reciben el "Diseño de personaje"
-- de la wiki (los que ya tenian una se dejan como estan).
--
-- Sin ficha en la wiki todavia: zzz-roxy.
--
-- Solo actualiza agentes que ya existen; no crea ninguno. Se puede repetir.
--
-- Generado el 2026-09-15.

update public.characters as c
set profile = v.profile,
    skills = v.skills,
    mindscapes = v.mindscapes,
    biography_es = coalesce(c.biography_es, v.biography),
    biography_source_es = case when c.biography_es is null and v.biography is not null then v.source else c.biography_source_es end
from (
  values
  ('zzz-caesar', '[{"campo":"Sexo","valor":"Femenino"},{"campo":"Afiliación","valor":"Hijos de Calidón"},{"campo":"Estatura","valor":"176"},{"campo":"Cumpleaños","valor":"16 de Marzo"},{"campo":"VA (CHS)","valor":"Su Ziwu (苏子芜)"},{"campo":"VA (JP)","valor":"Rina Satō (佐藤利奈)"},{"campo":"VA (KO)","valor":"Kim Bo-min (김보민)"},{"campo":"VA (EN)","valor":"Jennifer Sun Bell"},{"campo":"Versión de lanzamiento","valor":"1.2"}]'::jsonb, '{"categorias":[{"categoria":"Ataque normal","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/08/26/7c4749265d45177f16044c76d9315db0_7689331585667217268.png","tecnicas":[{"nombre":"Ataque normal: Corte desaforado","descripcion":"Pulsa para usarlo. Ejecuta hasta 6 cortes hacia delante, infligiendo daño físico."},{"nombre":"Ataque normal: ¡No hay marcha atrás!","descripcion":"Al contar con suficientes puntos de apoyo, mantén pulsado para usarlo. Consume 1 punto de apoyo para arrojar su escudo a su alrededor y golpear a los enemigos, infligiendo daño físico. Durante su ejecución, la agente se vuelve invulnerable."}],"atributos":[{"clave":"Ataque normal: Corte desaforado","valores":["Nivel 1","Nivel 2","Nivel 3","Nivel 4","Nivel 5","Nivel 6","Nivel 7","Nivel 8","Nivel 9","Nivel 10","Nivel 11","Nivel 12","Nivel 13","Nivel 14","Nivel 15","Nivel 16"]},{"clave":"Multiplicador de daño de 1.er golpe","valores":["47.2%","51.5%","55.8%","60.1%","64.4%","68.7%","73%","77.3%","81.6%","85.9%","90.2%","94.5%","98.8%","103.1%","107.4%","111.7%"]},{"clave":"Multiplicador de daño de 2.° golpe","valores":["40.9%","44.7%","48.5%","52.3%","56.1%","59.9%","63.7%","67.5%","71.3%","75.1%","78.9%","82.7%","86.5%","90.3%","94.1%","97.9%"]},{"clave":"Multiplicador de daño de 3.er golpe","valores":["148.3%","161.8%","175.3%","188.8%","202.3%","215.8%","229.3%","242.8%","256.3%","269.8%","283.3%","296.8%","310.3%","323.8%","337.3%","350.8%"]},{"clave":"Multiplicador de daño de 3.er golpe (alternativo)","valores":["118.4%","129.2%","140%","150.8