giendo daño físico.\nDurante su ejecución, la agente se vuelve invulnerable."}],"atributos":[{"clave":"Ataque rápido: Salto cortante","valores":["Nivel 1","Nivel 2","Nivel 3","Nivel 4","Nivel 5","Nivel 6","Nivel 7","Nivel 8","Nivel 9","Nivel 10","Nivel 11","Nivel 12","Nivel 13","Nivel 14","Nivel 15","Nivel 16"]},{"clave":"Multiplicador de daño de 1.er golpe","valores":["71.5%","78%","84.5%","91%","97.5%","104%","110.5%","117%","123.5%","130%","136.5%","143%","149.5%","156%","162.5%","169%"]},{"clave":"Multiplicador de Aturdimiento de 1.er golpe","valores":["35.8%","37.5%","39.2%","40.9%","42.6%","44.3%","46%","47.7%","49.4%","51%","52.8%","54.5%","56.2%","57.9%","59.6%","61.3%"]},{"clave":"Multiplicador de daño de 2.° golpe","valores":["71.5%","78%","84.5%","91%","97.5%","104%","110.5%","117%","123.5%","130%","136.5%","143%","149.5%","156%","162.5%","169%"]},{"clave":"Multiplicador de Aturdimiento de 2.° golpe","valores":["35.8%","37.5%","39.2%","40.9%","42.6%","44.3%","46%","47.7%","49.4%","51%","52.8%","54.5%","56.2%","57.9%","59.6%","61.3%"]},{"clave":"","valores":["","","","","","","","","","","","","","","",""]},{"clave":"Ataque rápido: Puñalada ilusoria","valores":["Nivel 1","Nivel 2","Nivel 3","Nivel 4","Nivel 5","Nivel 6","Nivel 7","Nivel 8","Nivel 9","Nivel 10","Nivel 11","Nivel 12","Nivel 13","Nivel 14","Nivel 15","Nivel 16"]},{"clave":"Multiplicador de daño","valores":["104.5%","114%","123.5%","133%","142.5%","152%","161.5%","171%","180.5%","190%","199.5%","209%","218.5%","228%","237.5%","247%"]},{"clave":"Multiplicador de Aturdimiento","valores":["52.3%","54.7%","57.1%","59.5%","61.9%","64.3%","66.7%","69.1%","71.5%","73.9%","76.3%","78.7%","81.1%","83.5%","85.9%","88.3%"]},{"clave":"","valores":["","","","","","","","","","","","","","","",""]},{"clave":"Contraataque: Sombra presta","valores":["Nivel 1","Nivel 2","Nivel 3","Nivel 4","Nivel 5","Nivel 6","Nivel 7","Nivel 8","Nivel 9","Nivel 10","Nivel 11","Nivel 12","Nivel 13","Nivel 14","Nivel 15","Nivel