ma afiliación que ella:\nAl ejecutar una técnica especial EX, técnica en cadena o una técnica definitiva, aumenta la Probabilidad de Crítico de Zhu Yuan en un 30% durante 10 s."}],"atributos":[{"clave":"Técnica pasiva: Munición especial","valores":["Nivel 1","Nivel 2 (A)","Nivel 3 (B)","Nivel 4 (C)","Nivel 5 (D)","Nivel 6 (E)","Nivel 7 (F)"]},{"clave":"Aumento de daño","valores":["20%","23.3%","26.6%","30%","33.3%","36.6%","40%"]},{"clave":"Aumento de daño adicional","valores":["20%","23.3%","26.6%","30%","33.3%","36.6%","40%"]},{"clave":"Daño Crítico","valores":["-","+9.6%","-","+9.6%","-","+9.6%","-"]},{"clave":"Ataque Base","valores":["-","-","+25","-","+25","-","+25"]}]}],"materiales":[{"desde":1,"hasta":2,"creditos":0,"materiales":[{"nombre":"ディニー","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/22/cd6682dd2d871dc93dfa28c3f281d527_7793444478727984954.png","cantidad":2000},{"nombre":"基礎エーテルチップ","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/05/eb5bbf56c9524ff906c04ecb3d879743_6067765112140253569.png","cantidad":2}]},{"desde":2,"hasta":3,"creditos":0,"materiales":[{"nombre":"ディニー","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/22/cd6682dd2d871dc93dfa28c3f281d527_7793444478727984954.png","cantidad":3000},{"nombre":"基礎エーテルチップ","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/05/eb5bbf56c9524ff906c04ecb3d879743_6067765112140253569.png","cantidad":3}]},{"desde":3,"hasta":4,"creditos":0,"materiales":[{"nombre":"ディニー","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/22/cd6682dd2d871dc93dfa28c3f281d527_7793444478727984954.png","cantidad":6000},{"nombre":"上級エーテルチップ","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/05/ad6c30133fe83326bbfa06807551cf2b_4657344893342165848.png","cantidad":2}]},{"desde":4,"hasta":5,"creditos":0,"materiales":[{"nombre":"ディニー","icono":"https://act-web