cd6682dd2d871dc93dfa28c3f281d527_7793444478727984954.png","cantidad":67500},{"nombre":"特化氷結チップ","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/05/7bc31e2a547a2febd1f19bd65a291cdc_7903533764672319126.png","cantidad":8}]},{"desde":9,"hasta":10,"creditos":0,"materiales":[{"nombre":"ディニー","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/22/cd6682dd2d871dc93dfa28c3f281d527_7793444478727984954.png","cantidad":90000},{"nombre":"特化氷結チップ","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/05/7bc31e2a547a2febd1f19bd65a291cdc_7903533764672319126.png","cantidad":10}]},{"desde":10,"hasta":11,"creditos":0,"materiales":[{"nombre":"ディニー","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/22/cd6682dd2d871dc93dfa28c3f281d527_7793444478727984954.png","cantidad":112500},{"nombre":"特化氷結チップ","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/05/7bc31e2a547a2febd1f19bd65a291cdc_7903533764672319126.png","cantidad":12}]},{"desde":11,"hasta":12,"creditos":0,"materiales":[{"nombre":"ディニー","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/22/cd6682dd2d871dc93dfa28c3f281d527_7793444478727984954.png","cantidad":135000},{"nombre":"特化氷結チップ","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/05/7bc31e2a547a2febd1f19bd65a291cdc_7903533764672319126.png","cantidad":15},{"nombre":"アクセサリ「ハムスターケージ」","icono":"https://act-upload.hoyoverse.com/event-ugc-hoyowiki/2024/07/23/59155606/a4cdec946097dff3fff67da1b6fe5c46_6008090676011765767.png","cantidad":1}]}]}'::jsonb, '[{"nivel":1,"nombre":"Presagio gélido","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/03/6335146d351f78f0a628618f2a849181_3119698053713316104.png","efecto":"Al golpear a un enemigo con un tijeretazo rápido al ejecutar ataque rápido: Asalto ártico, las cargas de congelación instantánea aumentan a 3. Al golpear a un enemigo con un tijeretazo cargado por medio de ataque rápido: Asalto ártico, las cargas de congelación instantánea aumentan a 6.\nPor cada carga de congelación instantánea consumida, aumenta la Probabilidad de Crítico de Ellen en un 2 % durante 15 s. Pueden acumularse hasta 6 cargas. La duración de cada carga es independiente.","cita":"Los vientos helados son el presagio más certero de que el invierno se acerca y también una señal inequívoca de que Ellen acaba de presentar una baja de largo tiempo para hibernar.\nAunque la pregunta es: ¿los tiburones necesitan hibernar?"},{"nivel":2,"nombre":"Depredadora ártica","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/03/469f9554aa138a057dacb98ede59a6d3_8037901845155267600.png","efecto":"Después de ejecutar el tercer golpe de ataque normal: Tijeretazo helado, puede conectarlo con técnica especial EX: Tiburonado.\nAl ejecutar una técnica especial EX, por cada carga de congelación instantánea que posea, aumenta el Daño Crítico de la técnica actual en un 20 %. Puede aumentar hasta un 60 %.","cita":"A pesar de estar manchadas de rojo, las gigantescas tijeras de Ellen carecen de calidez.\nLas frías hojas metálicas inspiran temor de convertirse en la próxima víctima."},{"nivel":3,"nombre":"Antihoras extras","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/03/28f2d7ccb68295e6b2c99fb99b577db4_8003165392045521961.png","efecto":"Nivel de ataque normal, evasión, técnica de apoyo, técnica especial y técnica en cadena +2","cita":"Esencialmente, «ser eficiente» significa volver a casa temprano.\nAsí que hay que golpear más rápido y con más fuerza."},{"nivel":4,"nombre":"Relente sempiterno","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/03/fc5c9f6a7297408a0823e8ff2d31f79e_3427042453878724993.png","efecto":"Cuando cualquier miembro del equipo congele o aturda a un enemigo, Ellen obtiene 6 ptos. de carga de congelación instantánea, obtiene el efecto de carga rápida y recupera 4 ptos. de energía. El efecto de recuperación puede activarse una vez cada 10 s.","cita":"Un sobrecogedor soplo de frío extremo.\nHasta las más aterradoras criaturas aprenderán lo cruel y hermoso que puede resultar el frío de la mano de Ellen.\nAunque, sin duda, los interminables turnos de trabajo que las empleadas domésticas tienen durante las vacaciones son aún más crueles..."},{"nivel":5,"nombre":"Sueño reparador","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/03/ada22c7100cfcd504dc951c773bb06b8_8375432747173267291.png","efecto":"Nivel de ataque normal, evasión, técnica de apoyo, técnica especial y técnica en cadena +2","cita":"Salvo en los combates más encarnizados, siempre parece que Ellen está a punto de caer dormida.\nMuchos son los enemigos que han encarado su muerte al subestimarla por ello."},{"nivel":6,"nombre":"Hora del ágape","icono":"https://act-webstatic.hoyoverse.com/event-static-hoyowiki-admin/2024/07/03/cc8354becbb5422d928dcc39ba6df7fa_4143672430113157989.png","efecto":"Al ejecutar una técnica especial EX, una técnica en cadena u obtener una carga rápida, aumenta la Tasa de Perforación de Ellen en un 20 % durante 6 s. Además, obtiene 1 carga de festín.\nPueden acumularse hasta 3 cargas. Al tener 3 cargas de festín, al ejecutar un tijeretazo cargado por medio de ataque rápido: Asalto ártico, consumirá todas las cargas de festín y aumentará el daño de dicha técnica en un 250 %.","cita":"Una herida abierta, una gota de sangre. Una escalofriante caza, un copioso banquete. Un precario destino, un instante de satisfacción."}]'::jsonb, null, null)
) as v(id, profile, skills, mindscapes, biography, source)
where c.id = v.id;
